    print(f"\nStanding Mandate Evals v0.1 — adapter: {adapter.name}")
    print(f"scenarios: {n}")
    print(f"ADH overall: {passed}/{n}" + (f"  ({passed / n:.0%})" if n else ""))
    for sub, vals in sorted(by_subtype.items()):
        print(f"  {sub:<11} {sum(vals)}/{len(vals)}")
    print("\nCOMP and ESC are NOT scored here — see rubric.md.")
    print("A high ADH score with no COMP/ESC review means nothing.\n")

    for r in results:
        mark = "ok  " if r["ADH"] else "FAIL"
        print(f"  [{mark}] {r['id']}")
        for b in r["breaches"]:
            print(f"           breach: {b}")

    pending = sum(len(r["needs_human_review"]) for r in results)
